-- ----------------------------
-- Table structure for js_app_comment
-- ----------------------------
DROP TABLE IF EXISTS `js_app_comment`;
CREATE TABLE `js_app_comment` (
  `id` varchar(64) NOT NULL COMMENT '编号',
  `category` varchar(10) DEFAULT NULL COMMENT '问题分类',
  `content` varchar(500) DEFAULT NULL COMMENT '问题和意见',
  `contact` varchar(200) DEFAULT NULL COMMENT '联系方式',
  `status` char(1) NOT NULL DEFAULT '0' COMMENT '状态（0正常 1删除 2停用）',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `remarks` varchar(500) DEFAULT NULL COMMENT '备注信息',
  `create_by_name` varchar(200) DEFAULT NULL COMMENT '提问人员姓名',
  `device_info` varchar(1000) DEFAULT NULL COMMENT '设备信息',
  `reply_date` date DEFAULT NULL COMMENT '回复时间',
  `reply_content` varchar(500) DEFAULT NULL COMMENT '回复意见',
  `reply_user_code` varchar(64) DEFAULT NULL COMMENT '回复人员',
  `reply_user_name` varchar(200) DEFAULT NULL COMMENT '回复人员姓名',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='APP意见反馈';

-- ----------------------------
-- Records of js_app_comment
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for js_app_upgrade
-- ----------------------------
