  `parent_code` varchar(64) NOT NULL COMMENT '父级编号',
  `parent_codes` varchar(767) NOT NULL COMMENT '所有父级编号',
  `tree_sort` decimal(10,0) NOT NULL COMMENT '排序号（升序）',
