-- ----------------------------
-- Table structure for js_cms_visit_log
-- ----------------------------
DROP TABLE IF EXISTS `js_cms_visit_log`;
CREATE TABLE `js_cms_visit_log` (
  `id` varchar(64) NOT NULL COMMENT '编号',
  `request_url` varchar(1000) DEFAULT NULL COMMENT '请求的URL地址',
  `request_url_host` varchar(128) DEFAULT NULL COMMENT '受访域名',
  `source_referer` varchar(1000) DEFAULT NULL COMMENT '来源页面/上一个页面',
  `source_referer_host` varchar(128) DEFAULT NULL COMMENT '来源域名',
  `source_type` char(1) DEFAULT NULL COMMENT '访问来源类型（1直接访问 2搜索引擎 3外部链接 4内部访问）',
  `search_engine` varchar(200) DEFAULT NULL COMMENT '使用的搜索引擎',
  `search_word` varchar(200) DEFAULT NULL COMMENT '搜索的关键词',
  `remote_addr` varchar(50) DEFAULT NULL COMMENT '客户IP地址',
  `user_agent` varchar(500) DEFAULT NULL COMMENT '用户代理字符串',
  `user_language` varchar(32) DEFAULT NULL COMMENT '客户机语言',
  `user_screen_size` varchar(32) DEFAULT NULL COMMENT '客户机屏幕大小0x0',
  `user_device` varchar(32) DEFAULT NULL COMMENT '客户机设备类型（电脑、平板、手机、未知）',
  `user_os_name` varchar(32) DEFAULT NULL COMMENT '客户机操作系统',
  `user_browser` varchar(32) DEFAULT NULL COMMENT '客户机浏览器',
  `user_browser_version` varchar(16) DEFAULT NULL COMMENT '浏览器版本',
  `unique_visit_id` varchar(64) DEFAULT NULL COMMENT '唯一访问标识',
  `visit_date` char(8) DEFAULT NULL COMMENT '本次访问日期（年月日）',
  `visit_time` datetime DEFAULT NULL COMMENT '本次访问时间',
  `is_new_visit` char(1) DEFAULT NULL COMMENT '是否新访问（30分内）',
  `first_visit_time` decimal(20,0) DEFAULT NULL COMMENT '首次访问时间戳（30分钟内）',
  `prev_remain_time` decimal(20,0) DEFAULT NULL COMMENT '上页面停留时间（秒）',
  `total_remain_time` decimal(20,0) DEFAULT NULL COMMENT '本次访问总停留时间（秒）',
  `site_code` varchar(64) DEFAULT NULL COMMENT '站点编码',
  `site_name` varchar(100) DEFAULT NULL COMMENT '站点名称',
  `category_code` varchar(64) DEFAULT NULL COMMENT '栏目编码',
  `category_name` varchar(100) DEFAULT NULL COMMENT '栏目名称',
  `content_id` varchar(64) DEFAULT NULL COMMENT '栏目内容编号',
  `content_title` varchar(255) DEFAULT NULL COMMENT '访问页面标题',
  `visit_user_code` varchar(100) DEFAULT NULL COMMENT '访问用户编码',
  `visit_user_name` varchar(100) DEFAULT NULL COMMENT '访问用户姓名',
  `corp_code` varchar(64) NOT NULL DEFAULT '0' COMMENT '租户代码',
  `corp_name` varchar(100) NOT NULL DEFAULT 'JeeSite' COMMENT '租户名称',
  PRIMARY KEY (`id`),
  KEY `cms_visit_log_cc` (`category_code`),
  KEY `cms_visit_log_ci` (`content_id`),
  KEY `cms_visit_log_fvt` (`first_visit_time`),
  KEY `cms_visit_log_inv` (`is_new_visit`),
  KEY `cms_visit_log_ra` (`remote_addr`),
  KEY `cms_visit_log_sc` (`site_code`),
  KEY `cms_visit_log_uvid` (`unique_visit_id`),
  KEY `cms_visit_log_vd` (`visit_date`),
  KEY `cms_visit_log_vt` (`visit_time`),
  KEY `idx_cms_visit_log_corpc` (`corp_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='访问日志表';

-- ----------------------------
-- Records of js_cms_visit_log
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for js_gen_table
-- ----------------------------
DROP TABLE IF EXISTS `js_gen_table`;
CREATE TABLE `js_gen_table` (
  `table_name` varchar(64) NOT NULL COMMENT '表名',
  `class_name` varchar(100) NOT NULL COMMENT '实体类名称',
  `comments` varchar(500) NOT NULL COMMENT '表说明',
  `parent_table_name` varchar(64) DEFAULT NULL COMMENT '关联父表的表名',
  `parent_table_fk_name` varchar(64) DEFAULT NULL COMMENT '本表关联父表的外键名',
  `data_source_name` varchar(64) DEFAULT NULL COMMENT '数据源名称',
  `tpl_category` varchar(200) DEFAULT NULL COMMENT '使用的模板',
  `package_name` varchar(500) DEFAULT NULL COMMENT '生成包路径',
  `module_name` varchar(30) DEFAULT NULL COMMENT '生成模块名',
  `sub_module_name` varchar(30) DEFAULT NULL COMMENT '生成子模块名',
  `function_name` varchar(200) DEFAULT NULL COMMENT '生成功能名',
  `function_name_simple` varchar(50) DEFAULT NULL COMMENT '生成功能名（简写）',
  `function_author` varchar(50) DEFAULT NULL COMMENT '生成功能作者',
  `gen_base_dir` varchar(1000) DEFAULT NULL COMMENT '生成基础路径',
  `gen_front_dir` varchar(1000) DEFAULT NULL COMMENT '生成前端路径',
  `options` varchar(1000) DEFAULT NULL COMMENT '其它生成选项',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `remarks` varchar(500) DEFAULT NULL COMMENT '备注信息',
  PRIMARY KEY (`table_name`),
  KEY `idx_gen_table_ptn` (`parent_table_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='代码生成表';

-- ----------------------------
-- Records of js_gen_table
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for js_gen_table_column
-- ----------------------------
DROP TABLE IF EXISTS `js_gen_table_column`;
CREATE TABLE `js_gen_table_column` (
  `id` varchar(64) NOT NULL COMMENT '编号',
  `table_name` varchar(64) NOT NULL COMMENT '表名',
  `column_name` varchar(64) NOT NULL COMMENT '列名',
  `column_sort` decimal(10,0) DEFAULT NULL COMMENT '列排序（升序）',
  `column_type` varchar(100) NOT NULL COMMENT '类型',
